void dfs(int v,int prev=-1){
    subtree[v]=1;
    min1[v]=v;
    for (auto it: adj[v]){
        if (it==prev) continue;
        dfs(it,v);
        subtree[v]+=subtree[it];
        min1[v]=min(min1[v],min1[it]);
    }
}
void find(int val){
    //cout << v << " " << u << " " << prevv << " " << prevu << " " << val << endl;
    if (v==val or u==val){
        ll a,b;
        if (subtree[prevv]>subtree[v] or prevv==-1) a=subtree[v];
        else a=n-subtree[prevv];
        if (subtree[prevu]>subtree[u] or prevu==-1) b=subtree[u];
        else b=n-subtree[prevu];
        ans[val]=le-a*b;
        //cout << a << " " << b << endl;
        le=a*b;
        return;
    }
    for (auto it: adj[v]){
        if (it==prevv) continue;
        if (min1[it]==val){
            if (v==u) prevu=it;
            prevv=v;
            v=it;
            vis[it]=1;

            find(val);
            return;
        }  
    }
    for (auto it: adj[u]){
        if (it==prevu) continue;
        if (min1[it]==val){
            prevu=u;
            u=it;
            vis[it]=1;
            find(val);
            return;
        }  
    }
    ans[val]=le;
    le=0;
}
